<div role="tabpanel" id="panel-student" aria-labelledby="tab-student" x-show="tab==='student'" class="space-y-4"><x-capstone::alert title="Bursa Ide View Only" icon="Lock" x-show="!canJoin"><span x-text="reasonText[flow?.reason] || (group?.title_id ? 'Anda sudah memiliki judul tetap. Fitur bergabung tidak lagi tersedia.' : 'Fitur bergabung hanya untuk mahasiswa tanpa kelompok atau ketua kelompok seeker.')"></span></x-capstone::alert><div x-show="!studentIdeas.length" class="text-center py-12 text-muted-foreground border rounded-lg border-dashed"><x-capstone::icon name="Lightbulb" class="h-10 w-10 mx-auto mb-2 opacity-20" />No student-proposed ideas found yet.</div><div class="grid gap-4 md:grid-cols-2"><template x-for="title in studentIdeas" :key="title.id"><x-capstone::card class="flex flex-col"><div class="px-6 pb-2 flex justify-between items-start gap-2"><div class="space-y-1 min-w-0"><h2 class="text-base font-semibold line-clamp-1" x-text="title.title"></h2><p class="text-xs text-muted-foreground">By <span x-text="person(title.proposed_by_group?.members?.find(m=>m.is_leader)?.student)"></span></p></div><x-capstone::badge variant="secondary" x-text="slots(title)>0?slots(title)+' slots':'FULL'" /></div><div class="px-6 flex-1 space-y-4"><p class="text-sm text-muted-foreground line-clamp-3" x-text="title.description"></p><div class="flex flex-wrap gap-1"><template x-for="spec in title.specializations || []" :key="spec"><x-capstone::badge variant="outline" class="text-[10px]" x-text="spec" /></template></div><div class="flex items-center gap-2 text-xs text-muted-foreground pt-2 border-t"><x-capstone::icon name="User" class="h-3 w-3" /><span>Proposed Supervisor: <span x-text="person(title.proposed_supervisor)"></span></span></div></div><div class="bg-muted/10 p-3 pt-0"><x-capstone::button size="sm" class="w-full" @click="request(title)" ::disabled="!canRequest(title)"><x-capstone::icon name="Send" class="h-3 w-3" /><span x-text="joinLabel(title)"></span></x-capstone::button></div></x-capstone::card></template></div></div>
